// ==============================
// BAD WORDS LIST
// ==============================

const badWords = [
  "fuck","fucking","fucker","motherfucker","mother fucker","mf",
  "shit","bullshit","shithead",
  "bitch","bitches",
  "ass","asshole",
  "bastard",
  "slut","whore",
  "idiot","stupid","dumb","moron","loser",
  "bloody","hell",
  "poda","podi","dei","di",
  "loosu","kirukku","muttal","naaye",
  "thevidiya","thevdiya","otha","otha dei","otha di",
  "sunni","poolu","punda","pundai","koothi",
  "mayiru","kena","kena payale"
];

// ==============================
// FORM DATA FROM WEBHOOK
// ==============================

const form = $("Webhook").first().json.body;

const feedback = (form.feedback || "").toLowerCase();

// ==============================
// BAD WORD CHECK
// ==============================

const hasBadWord = badWords.some(word =>
  feedback.includes(word.toLowerCase())
);

if (hasBadWord) {
  return [{
    json: {
      allowed: false,
      message: "Feedback contains inappropriate words."
    }
  }];
}

// ==============================
// MATCH GOOGLE SHEET
// ==============================

const output = [];

for (const item of $input.all()) {

  const row = item.json;

  if (
    String(row.Year || "").trim().toLowerCase() === String(form.year || "").trim().toLowerCase() &&
    String(row.Department || "").trim().toLowerCase() === String(form.department || "").trim().toLowerCase() &&
    String(row.Subject || "").trim().toLowerCase() === String(form.subject || "").trim().toLowerCase() &&
    String(row["Staff Name"] || "").trim().toLowerCase() === String(form.staff || "").trim().toLowerCase()
  ) {

    output.push({
      json: {

        allowed: true,

        // Google Sheet column name
        email: row["Mail Id"],

        year: form.year,
        department: form.department,
        subject: form.subject,
        staff: form.staff,
        feedback: form.feedback,

        // Debug values
        matchedEmail: row["Mail Id"],
        matchedRow: row.row_number

      }
    });

  }

}

// ==============================
// NO MATCH FOUND
// ==============================

if (output.length === 0) {

  return [{
    json: {
      allowed: false,
      message: "No matching staff found in Google Sheet."
    }
  }];

}

return output;

